{"text": "This is an Express server.  All routes are handled within `app.js` for simplicity. Error handling and modularity best practices are implemented.", "fileTree": {"app.js": {"file": {"contents": "const express = require('express');
const app = express();
const port = 3000;

// Middleware to parse JSON request bodies
app.use(express.json());

// Sample GET route
app.get('/hello', (req, res) => {
  res.send('Hello from Express!');
});

// Sample POST route with error handling
app.post('/add', (req, res) => {
  try {
    const num1 = parseFloat(req.body.num1);
    const num2 = parseFloat(req.body.num2);
    if (isNaN(num1) || isNaN(num2)) {
      return res.status(400).json({ error: 'Invalid input. Numbers expected.' });
    }
    const sum = num1 + num2;
    res.json({ sum });
  } catch (error) {
    console.error('Error processing POST request:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Error handling middleware for 404
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});

// Error handling middleware for other errors
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal server error' });
});

app.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});"}}}, "package.json": {"file": {"contents": "{
